package run.ikaros.music; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/v2/music/queues") public class MusicQueueController {private final MusicQueueService service; public MusicQueueController(MusicQueueService s){service=s;} @PostMapping public Mono<MusicQueueView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@Valid@RequestBody CreateMusicQueueRequest r){return service.create(o,r);}@GetMapping("/{queueId}/entries")public Flux<MusicQueueEntryView> entries(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID queueId){return service.entries(o,queueId);}@PatchMapping("/{queueId}/policy")public Mono<MusicQueueView> policy(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID queueId,@Valid@RequestBody UpdateMusicQueuePolicyRequest r){return service.policy(o,queueId,r);}@DeleteMapping("/entries/{entryId}")public Mono<Void> remove(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID entryId){return service.remove(o,entryId);}}
